// Basic file generated by AI: https://chatgpt.com/share/6921fec2-7724-800c-920b-0850dc0d393a
import {
    OPENAI_API_TEMPERATURE,
    OPENAI_PLAN_GENERATION_MODEL,
    OPENAI_PROGRAM_UPDATE_MODEL,
} from "../services/config/apiConfig.js";
import { db } from "../services/config/firebase.js";
import { getFunctions, httpsCallable } from "../services/config/firebaseSdk";
import {
    buildTrainingPlanScaffold,
    buildMissedSessionAdjustmentPrompt,
    buildTrainingPrompt,
} from "../services/utils/promptBuilder.js";
import {
    normalizeTrainingDay,
    parseGeneratedTrainingPlan,
} from "../services/utils/trainingPlan.js";
import { applyMissingProgramMaxBridges } from "../services/utils/missingProgramMaxBridge.js";

function findGeneratedWeek(generatedWeeks = [], scaffoldWeek = {}, weekIndex = 0) {
    return (
        generatedWeeks.find((week) => week?.week === scaffoldWeek.week) ||
        generatedWeeks[weekIndex] ||
        {}
    );
}

function findGeneratedDay(generatedDays = [], scaffoldDay = {}, dayIndex = 0) {
    return (
        generatedDays.find((day) => day?.day === scaffoldDay.day) ||
        generatedDays[dayIndex] ||
        {}
    );
}

function applyTrainingPlanScaffold(plan = {}, scaffold = null) {
    if (!scaffold?.weeks?.length) {
        return plan;
    }

    const generatedWeeks = Array.isArray(plan?.weeks) ? plan.weeks : [];

    return {
        ...plan,
        phaseOverview: Array.isArray(plan?.phaseOverview) && plan.phaseOverview.length > 0
            ? plan.phaseOverview
            : scaffold.phaseOverview,
        weeks: scaffold.weeks.map((scaffoldWeek, weekIndex) => {
            const generatedWeek = findGeneratedWeek(
                generatedWeeks,
                scaffoldWeek,
                weekIndex
            );
            const generatedDays = Array.isArray(generatedWeek?.days)
                ? generatedWeek.days
                : [];

            return {
                ...generatedWeek,
                week: scaffoldWeek.week,
                days: scaffoldWeek.days.map((scaffoldDay, dayIndex) => {
                    const generatedDay = findGeneratedDay(
                        generatedDays,
                        scaffoldDay,
                        dayIndex
                    );

                    return {
                        ...generatedDay,
                        ...scaffoldDay,
                        sessionProfile: generatedDay.sessionProfile,
                        exercises: generatedDay.exercises,
                    };
                }),
            };
        }),
    };
}

function normalizeGeneratedPlan(plan = {}, scaffold = null, userInput = {}) {
    return parseGeneratedTrainingPlan(
        applyMissingProgramMaxBridges(
            applyTrainingPlanScaffold(plan, scaffold),
            userInput
        )
    );
}

const TRAINING_PLAN_CALL_TIMEOUT_MS = 300000;

async function getTrainingCallableResponse(
    messages = [],
    modelName = OPENAI_PLAN_GENERATION_MODEL,
    options = {}
) {
    const functions = getFunctions(db.app, "us-central1");
    const generateTrainingPlanCallable = httpsCallable(
        functions,
        "generateTrainingPlan",
        { timeout: TRAINING_PLAN_CALL_TIMEOUT_MS }
    );

    return generateTrainingPlanCallable({
        model: modelName,
        temperature: OPENAI_API_TEMPERATURE,
        messages,
        generationIntent: options.generationIntent || ""
    }).then((result) => {
        if (!result?.data?.success || !result?.data?.plan) {
            throw new Error("No training plan returned from the server.");
        }

        return {
            plan: result.data.plan,
            regenerationUsage: result.data.regenerationUsage || null,
        };
    });
}

export async function generatePlan(userInput, oldPlan = null, options = {}) {
    const scaffold = buildTrainingPlanScaffold(userInput);
    const prompt = buildTrainingPrompt(userInput, oldPlan);
    const messages = [
        {
            role: "system",
            content: prompt
        }
    ];

    return getTrainingCallableResponse(
        messages,
        OPENAI_PLAN_GENERATION_MODEL,
        options
    ).then((result) => ({
        plan: normalizeGeneratedPlan(result.plan, scaffold, userInput),
        regenerationUsage: result.regenerationUsage,
    }));
}

export async function adjustTrainingDayForMissedSession(adjustmentInput = {}) {
    const prompt = buildMissedSessionAdjustmentPrompt(adjustmentInput);
    const messages = [
        {
            role: "system",
            content: prompt
        }
    ];

    return getTrainingCallableResponse(
        messages,
        OPENAI_PROGRAM_UPDATE_MODEL
    ).then((result) =>
        normalizeTrainingDay(
            {
                ...result.plan,
                day: adjustmentInput?.targetDay?.day || result.plan?.day || 1,
                preferredWeekday:
                    adjustmentInput?.targetDay?.preferredWeekday ||
                    result.plan?.preferredWeekday ||
                    "",
            },
            (adjustmentInput?.targetDay?.day || result.plan?.day || 1) - 1
        )
    );
}
